import{_ as o,o as t,c as a,ae as r}from"./chunks/framework.B2FZg54p.js";const s="/heidrun/experiments/web-doc-by-ai/documentation_images/files/files_sidebar.png",w=JSON.parse('{"title":"Browse and open project files","description":"","frontmatter":{},"headers":[],"relativePath":"documentation/browse_project_files.md","filePath":"documentation/browse_project_files.md"}'),i={name:"documentation/browse_project_files.md"};function n(l,e,c,h,d,p){return t(),a("div",null,[...e[0]||(e[0]=[r('<h1 id="browse-and-open-project-files" tabindex="-1">Browse and open project files <a class="header-anchor" href="#browse-and-open-project-files" aria-label="Permalink to &quot;Browse and open project files&quot;">​</a></h1><p>Find a file in the selected workspace and view the file in the large Git window.</p><h2 id="select-an-existing-workspace" tabindex="-1">Select an existing workspace <a class="header-anchor" href="#select-an-existing-workspace" aria-label="Permalink to &quot;Select an existing workspace&quot;">​</a></h2><p>A workspace is a project folder. Choose a workspace that contains a Git repository.</p><ol><li>Click the workspace name at the left end of the status bar to open the workspace information card, a small card with details and a list of workspaces.</li><li>Click the workspace you want in the list below the details.</li></ol><p>If no suitable workspace is listed, add and select a workspace:</p><ol><li>Click <strong>New workspace…</strong> at the end of the workspace information card.</li><li>Choose the repository folder in the folder chooser.</li><li>Click the workspace name in the status bar to reopen the workspace information card.</li><li>Click the new workspace entry in the list below the details.</li></ol><p>The workspace information card closes, and the status bar shows the selected workspace name.</p><h2 id="open-a-project-file" tabindex="-1">Open a project file <a class="header-anchor" href="#open-a-project-file" aria-label="Permalink to &quot;Open a project file&quot;">​</a></h2><p>The Files sidebar section shows the folder tree of the selected workspace&#39;s Git repository.</p><ol><li>Click <strong>Files</strong>, the first folder icon in the left sidebar icon bar, the narrow vertical bar at the outer edge of the left sidebar, above <strong>Scripts</strong>.</li><li>Click the containing folder rows to unfold the folders and locate the file.</li></ol><p><img src="'+s+'" alt="Files sidebar section with docs unfolded and docs/README.md selected in the folder tree."></p><ol start="3"><li>Click the file row you want to open.</li></ol><p>The file row becomes selected, and the large Git window opens over the application to show the file. Use <strong>File</strong> to view the whole file, or <strong>Diff</strong> or <strong>Side by side</strong> to compare changes. For an unchanged file, <strong>Diff</strong> and <strong>Side by side</strong> are disabled; the whole file is shown, or formatted Markdown if <strong>Reading</strong> is selected.</p><p>When finished viewing, you can press <strong>Escape</strong> or click <strong>Close</strong>, the cross at the top-right of the large Git window, to return to the Files sidebar section. The file row remains selected.</p><h2 id="refresh-the-folder-tree" tabindex="-1">Refresh the folder tree <a class="header-anchor" href="#refresh-the-folder-tree" aria-label="Permalink to &quot;Refresh the folder tree&quot;">​</a></h2><p>Use <strong>Refresh</strong> when a file or folder was added or removed outside Heidrun and the folder tree still shows the old list.</p><ol><li>Click <strong>Refresh</strong>, the circular arrow in the header of the Files sidebar section.</li><li>If necessary, click the folder where the change was made to unfold the folder.</li></ol><p>Check that an added file now appears or a removed file no longer appears. Refresh also removes a remembered empty folder from the folder tree when the folder no longer exists on disk.</p><h2 id="troubleshooting" tabindex="-1">Troubleshooting <a class="header-anchor" href="#troubleshooting" aria-label="Permalink to &quot;Troubleshooting&quot;">​</a></h2><section class="documentation-troubleshooting-topic" aria-label="“Select a workspace.” appears"><h3 id="select-a-workspace-appears" tabindex="-1">“Select a workspace.” appears <a class="header-anchor" href="#select-a-workspace-appears" aria-label="Permalink to &quot;“Select a workspace.” appears&quot;">​</a></h3><p><strong>Cause</strong>: No workspace is selected.</p><p><strong>Solution</strong>:</p><ol><li><a href="#select-an-existing-workspace">Select an existing workspace</a> that contains a Git repository.</li></ol><p><strong>Check</strong>: The Files sidebar section shows the folder tree when the selected workspace is a Git repository.</p></section><section class="documentation-troubleshooting-topic" aria-label="“This workspace is not a Git repository.” appears"><h3 id="this-workspace-is-not-a-git-repository-appears" tabindex="-1">“This workspace is not a Git repository.” appears <a class="header-anchor" href="#this-workspace-is-not-a-git-repository-appears" aria-label="Permalink to &quot;“This workspace is not a Git repository.” appears&quot;">​</a></h3><p><strong>Cause</strong>: The selected workspace is not a Git repository.</p><p><strong>Solution</strong>:</p><ol><li><a href="#select-an-existing-workspace">Select an existing workspace</a> that contains a Git repository.</li></ol><p><strong>Check</strong>: The Files sidebar section shows the repository&#39;s folder tree.</p></section><section class="documentation-troubleshooting-topic" aria-label="Long file lists"><h3 id="long-file-lists" tabindex="-1">Long file lists <a class="header-anchor" href="#long-file-lists" aria-label="Permalink to &quot;Long file lists&quot;">​</a></h3><p>“The list is too long: only the first files are shown.” means that only the first 50,000 entries are available. Heidrun has no control to load the remaining entries.</p><p>Check the selected workspace in the status bar and unfold the file&#39;s containing folders. If the file is still missing while the warning appears, the folder tree may be incomplete.</p></section><h2 id="related-pages" tabindex="-1">Related pages <a class="header-anchor" href="#related-pages" aria-label="Permalink to &quot;Related pages&quot;">​</a></h2><ul><li><a href="/heidrun/experiments/web-doc-by-ai/documentation/create_a_file_or_folder.html">Create a file or folder</a>: to add an empty file or folder in the intended location.</li><li><a href="/heidrun/experiments/web-doc-by-ai/documentation/copy_a_file_path.html">Copy a file path</a>: to use a file path outside Heidrun.</li><li><a href="/heidrun/experiments/web-doc-by-ai/documentation/files_sidebar_section_controls.html">Files sidebar section controls</a>: to look up buttons and folder tree indicators.</li><li><a href="/heidrun/experiments/web-doc-by-ai/documentation/shortcuts.html">Keyboard shortcuts</a>: to find the shortcut <strong>⌘P</strong> for opening a project file by name.</li></ul>',25)])])}const g=o(i,[["render",n]]);export{w as __pageData,g as default};
